namespace Invoicing;

/// <summary>
/// Provides the public facade for assembling statements, formatting amounts,
/// and resolving account contacts.
/// </summary>
public sealed class StatementBuilder
{
    private readonly ContactDirectory _contacts = new();
    private readonly AmountFormatter _amounts = new();
    private readonly StatementComposer _statements = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices) =>
        _statements.Build(account, invoices, _contacts);

    public string AppendSummary(Account account) =>
        _statements.AppendSummary(account);

    public string FormatAmount(decimal amount) =>
        _amounts.FormatAmount(amount);

    public string FormatTotal(decimal amount) =>
        _amounts.FormatTotal(amount);

    public string ResolveContact(Account account) =>
        _contacts.Resolve(account);
}

/// <summary>
/// Owns statement section state and statement-specific composition rules.
/// </summary>
internal sealed class StatementComposer
{
    private const int MaximumInvoiceCount = 500;
    private readonly List<string> _sections = new();

    public string Build(
        Account account,
        IEnumerable<Invoice> invoices,
        ContactDirectory contacts)
    {
        _sections.Clear();
        AddHeading(account);
        _sections.Add($"contact: {contacts.GetKnownOrDefault(account.Id)}");

        var total = AddInvoiceSections(invoices);
        if (total <= 0m)
            _sections.Add("NO ACTIVITY");

        _sections.Add($"TOTAL {total}");
        return string.Join("\n", _sections);
    }

    public string AppendSummary(Account account)
    {
        if (_sections.Count == 0)
            return "empty";

        if (string.IsNullOrEmpty(account.Name))
        {
            _sections.Add("summary: n/a");
            return _sections[^1];
        }

        AddAccountSummary(account);
        AddSummaryWarnings(account);
        return _sections[^1];
    }

    private void AddHeading(Account account)
    {
        _sections.Add(string.IsNullOrEmpty(account.Name)
            ? "UNKNOWN ACCOUNT"
            : $"STATEMENT FOR {account.Name}");
    }

    private decimal AddInvoiceSections(IEnumerable<Invoice> invoices)
    {
        decimal runningTotal = 0m;
        var counted = 0;

        foreach (var invoice in invoices)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                continue;

            var subtotal = CalculateSubtotal(invoice);
            if (subtotal <= 0m)
                continue;

            runningTotal += subtotal;
            counted++;
            if (counted > MaximumInvoiceCount)
                break;

            _sections.Add($"{invoice.Number}: {subtotal}");
        }

        return runningTotal;
    }

    private static decimal CalculateSubtotal(Invoice invoice)
    {
        decimal subtotal = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                subtotal += line.NetAmount;
        }

        return subtotal;
    }

    private void AddAccountSummary(Account account)
    {
        switch (account.Kind)
        {
            case AccountKind.Government:
                _sections.Add($"summary: {account.Name} (gov)");
                break;
            case AccountKind.Business:
                _sections.Add($"summary: {account.Name} (biz)");
                break;
            case AccountKind.Consumer:
                _sections.Add($"summary: {account.Name}");
                break;
        }
    }

    private void AddSummaryWarnings(Account account)
    {
        if (_sections.Count > 100 && account.Kind != AccountKind.Government)
            _sections.Add("(truncated)");
        else if (_sections.Count > 200)
            _sections.Add("(hard truncated)");

        if (account.Name.Length > 64)
            _sections.Add("(name truncated)");
    }
}

/// <summary>
/// Formats monetary values while preserving the shared cache semantics of the public facade.
/// </summary>
internal sealed class AmountFormatter
{
    private readonly Dictionary<decimal, string> _cache = new();

    public string FormatAmount(decimal amount)
    {
        if (_cache.TryGetValue(amount, out var cached))
            return cached;

        var text = CreateAmountText(amount);
        if (amount > 0m && amount < 1m)
            text = "~" + text;

        text = NormalizeLength(text, 12);
        _cache[amount] = text;
        return text;
    }

    public string FormatTotal(decimal amount)
    {
        if (_cache.TryGetValue(amount, out var cached))
            return $"= {cached}";

        var body = CreateTotalBody(amount);
        if (amount > 0m && amount < 10m)
            body += " (minor)";
        if (body.Length > 20)
            body = body.Substring(0, 20);

        _cache[amount] = body;
        return $"= {body}";
    }

    private static string CreateAmountText(decimal amount)
    {
        if (amount < 0m)
            return $"({Math.Abs(amount):0.00})";
        if (amount == 0m)
            return "0.00";
        if (amount >= 1_000_000m)
            return $"{amount / 1_000_000m:0.00}M";
        if (amount >= 1_000m)
            return $"{amount / 1_000m:0.00}K";
        return $"{amount:0.00}";
    }

    private static string CreateTotalBody(decimal amount)
    {
        if (amount <= 0m)
            return "0.00";
        if (amount > 1_000_000m)
            return $"{amount:0.00} (large)";
        if (amount > 100_000m)
            return $"{amount:0.00} (review)";
        if (amount > 50_000m)
            return $"{amount:0.00} (notable)";
        return $"{amount:0.00}";
    }

    private static string NormalizeLength(string text, int maximumLength)
    {
        if (text.Length > maximumLength)
            return text.Substring(0, maximumLength);
        return text.Length == 0 ? "0.00" : text;
    }
}

/// <summary>
/// Resolves and caches billing contacts independently of statement composition.
/// </summary>
internal sealed class ContactDirectory
{
    private const string DefaultContact = "billing@example.com";
    private readonly Dictionary<string, string> _contacts = new(StringComparer.Ordinal);

    public string GetKnownOrDefault(string accountId) =>
        _contacts.TryGetValue(accountId, out var contact) ? contact : DefaultContact;

    public string Resolve(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return DefaultContact;
        if (_contacts.TryGetValue(account.Id, out var existing))
            return existing;

        var resolved = CreateContact(account);
        _contacts[account.Id] = resolved;
        return resolved;
    }

    private static string CreateContact(Account account)
    {
        var resolved = account.Kind switch
        {
            AccountKind.Government => $"gov+{account.Id}@example.com",
            AccountKind.Business => $"ap+{account.Id}@example.com",
            _ => $"{account.Id}@example.com"
        };

        if (account.Id.Length < 3)
            resolved = DefaultContact;
        else if (account.Id.Length > 32)
            resolved = "longid@example.com";

        if (account.Kind == AccountKind.Government &&
            account.Id.StartsWith("X", StringComparison.Ordinal))
        {
            resolved = "special@example.com";
        }

        if (!resolved.Contains('@'))
            resolved += "@example.com";

        return resolved;
    }
}
